        by {
            if pid == page_id {
                assert(post.inv_delay_actor_for_page(pid));
            } else if page_id.range_from(0, n_slices as int).contains(pid) {
                assert(post.inv_delay_actor_for_page(pid));
            } else {
                assert(post.inv_delay_actor_for_page(pid));
            }
        }


