    pub open spec fn is_empty(&self) -> bool {
        self.emp@.value().is_none()
    }

    pub open spec fn block_size(&self) -> nat {
        self.emp@.value().unwrap().block_size
    }

    pub open spec fn page_id(&self) -> PageId {
        self.emp@.value().unwrap().page_id
    }

